(5491608, 790198, 79816, '<td valign="top">I really like the bottom half, but I don''t get the connection with the monitor. Sorry! Still giving an OK score because of the great lighting and scene.</td>', 'I really like the bottom half, but I don''t get the connection with the monitor. Sorry! Still giving an OK score because of the great lighting and scene.', '2009-05-18 18:48:23.000000', NULL, 1),
(5491633, 791493, 37845, '<td valign="top">Really effective use of tilt shifting here. Well done.</td>', 'Really effective use of tilt shifting here. Well done.', '2009-05-18 19:13:17.000000', NULL, 1),
