(5491645, 791833, 37845, '<td valign="top">As miniature, Im not sure this works. But as an abstract, I think this shot in phenominal. I wont leave a vote because it doesnt meet the challenge IMO, but this is in my favourites because I really like it.</td>', 'As miniature, Im not sure this works. But as an abstract, I think this shot in phenominal. I wont leave a vote because it doesnt meet the challenge IMO, but this is in my favourites because I really like it.', '2009-05-18 19:25:28.000000', NULL, 1),
(5491653, 791841, 37845, '<td valign="top">Nice use of tilt shifting. Your effect is convincingly miniature.</td>', 'Nice use of tilt shifting. Your effect is convincingly miniature.', '2009-05-18 19:32:52.000000', NULL, 1),
(5491655, 790978, 37845, '<td valign="top">Ugh.... another picture of toys....<br/> <br/>Wait a second... tilt shifting :D<br/> <br/>Nice use of tilt shifting here.</td>', 'Ugh.... another picture of toys.... Wait a second... tilt shifting :D Nice use of tilt shifting here.', '2009-05-18 19:35:13.000000', NULL, 1),
(5491838, 791840, 43774, '<td valign="top">Very good processing to make this look like a miniature train set.</td>', 'Very good processing to make this look like a miniature train set.', '2009-05-18 22:25:51.000000', NULL, 1),
(5491839, 791691, 43774, '<td valign="top">Cute and a cute title too.</td>', 'Cute and a cute title too.', '2009-05-18 22:26:01.000000', NULL, 1),
