(5498130, 791833, 50695, '<td valign="top">This is stunning, whatever the hell it is.<br/> <br/>Okay, I gave ribbons to three photos that I felt met the challenge in an interesting way, but I can''t just ignore this shot, so I''m giving two yellows.<br/> <br/><img alt="'' . substr(''//blackyak.com/dpc/yellowpost.jpg'', strrpos(''//blackyak.com/dpc/yellowpost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/yellowpost.jpg"/></td>', 'This is stunning, whatever the hell it is. Okay, I gave ribbons to three photos that I felt met the challenge in an interesting way, but I can''t just ignore this shot, so I''m giving two yellows. ', '2009-05-24 11:23:02.000000', NULL, 1),
(5498254, 790493, 92939, '<td valign="top">Love it</td>', 'Love it', '2009-05-24 13:49:02.000000', NULL, 1),
(5498362, 791493, 1031, '<td valign="top">Apparently a lot of voters don''t include this type of shot in the category of "miniature" -- in this case, I''d suggest even more blurring towards the top and bottom regions to make the effect even more pronounced. Your composition and subjects are fine.</td>', 'Apparently a lot of voters don''t include this type of shot in the category of "miniature" -- in this case, I''d suggest even more blurring towards the top and bottom regions to make the effect even more pronounced. Your composition and subjects are fine.', '2009-05-24 17:01:13.000000', NULL, 1),
(5498365, 791779, 1031, '<td valign="top">How appropriate for Indy 500 weekend ... I haven''t played with slot cars for a long time!</td>', 'How appropriate for Indy 500 weekend ... I haven''t played with slot cars for a long time!', '2009-05-24 17:03:14.000000', NULL, 1),
